import json, sys, datetime

def txt(x, n=400):
    if isinstance(x, str):
        return x[:n]
    return str(x)[:n]

def parse_ts(s):
    try:
        return datetime.datetime.fromisoformat(s.replace('Z', '+00:00'))
    except Exception:
        return None

def main(path):
    lines = open(path).readlines()
    out = []
    prev_ts = None
    for l in lines:
        try:
            d = json.loads(l)
        except Exception:
            continue
        t = d.get('type')
        ts = d.get('timestamp')
        tsdt = parse_ts(ts) if ts else None
        gap = None
        if tsdt and prev_ts:
            gap = (tsdt - prev_ts).total_seconds()
        if tsdt:
            prev_ts = tsdt

        if t == 'user':
            msg = d.get('message', {})
            content = msg.get('content') if isinstance(msg, dict) else None
            if isinstance(content, str):
                out.append(('USER', ts, gap, txt(content, 600)))
            elif isinstance(content, list):
                for c in content:
                    if isinstance(c, dict) and c.get('type') == 'text':
                        out.append(('USER', ts, gap, txt(c.get('text'), 600)))
                    elif isinstance(c, dict) and c.get('type') == 'tool_result':
                        cc = c.get('content')
                        if isinstance(cc, list):
                            cc = ' '.join(txt(x.get('text','')) for x in cc if isinstance(x, dict))
                        out.append(('TOOL_RESULT', ts, gap, txt(cc, 300)))
        elif t == 'assistant':
            msg = d.get('message', {})
            content = msg.get('content') if isinstance(msg, dict) else None
            if isinstance(content, list):
                for c in content:
                    if not isinstance(c, dict):
                        continue
                    if c.get('type') == 'text':
                        out.append(('ASSISTANT', ts, gap, txt(c.get('text'), 500)))
                    elif c.get('type') == 'tool_use':
                        out.append(('TOOL_USE', ts, gap, f"{c.get('name')}: {txt(c.get('input'), 250)}"))
        elif t == 'attachment' or 'attachment' in d:
            att = d.get('attachment')
            if att and isinstance(att, dict):
                hookname = att.get('hookName') or att.get('type')
                out.append(('HOOK', ts, gap, txt(f"{hookname}: {att.get('content','')}", 150)))
    for role, ts, gap, content in out:
        gapstr = f"[+{gap:.0f}s]" if gap and gap > 20 else ""
        print(f"{ts} {gapstr} {role}: {content}".replace('\n', ' \\n '))

if __name__ == '__main__':
    main(sys.argv[1])

